import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";

type Msg = {
  from: "master" | "you";
  time: string;
  text: string;
  photo?: string;
};

export default function Garage24MasterChat() {
  const reduced = useReducedMotion();
  const [count, setCount] = useState(reduced ? 4 : 0);

  useEffect(() => {
    if (reduced) return;
    if (count >= 4) return;
    const t = setTimeout(() => setCount((c) => c + 1), 900 + count * 200);
    return () => clearTimeout(t);
  }, [count, reduced]);

  const messages: Msg[] = [
    {
      from: "you",
      time: "09:12",
      text: "Здравствуйте. Стук спереди справа на кочках, когда сможете посмотреть?",
    },
    {
      from: "master",
      time: "09:14",
      text: "Добрый день. Подъёмник свободен в 11:30, заезжайте. Диагностика ходовой 900 ₽.",
    },
    {
      from: "master",
      time: "13:05",
      text: "Нашёл причину: стойка стабилизатора и втулка. Заменим сегодня, к 18:00 будет готова.",
      photo: "Фото: домкратная стойка, пыльник в трещинах",
    },
    {
      from: "master",
      time: "17:40",
      text: "Готово. Стойка и втулка заменены, стук ушёл. Гарантия на работы 12 месяцев. Счёт в следующем сообщении.",
      photo: "Фото: новая стойка установлена на место",
    },
  ];

  const stages = [
    { label: "Заявка", done: true },
    { label: "Диагностика", done: true },
    { label: "Ремонт", done: true },
    { label: "Контроль", done: false },
    { label: "Выдача", done: false },
  ];

  return (
    <section className="relative overflow-hidden bg-background py-16 md:py-24">
      <div className="mx-auto max-w-6xl px-4">
        <div className="grid items-center gap-10 md:grid-cols-2">
          <div>
            <p className="text-sm font-medium text-muted-foreground">
              Химмаш, Екатеринбург
            </p>
            <h2 className="mt-3 text-3xl font-semibold tracking-tight text-foreground md:text-4xl">
              Статус ремонта без звонков
            </h2>
            <p className="mt-4 max-w-md text-base leading-relaxed text-muted-foreground">
              Мастер пишет в Telegram сам: что нашёл, что заменил, фото работ и
              срок готовности. Средний ремонт занимает один день, звать и
              спрашивать не нужно.
            </p>

            <div className="mt-8 space-y-3">
              {stages.map((s, i) => {
                const active =
                  !reduced && s.done && (i < stages.findIndex((x) => !x.done) || s.done);
                return (
                  <div key={s.label} className="flex items-center gap-3">
                    <span
                      className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border text-xs font-semibold ${
                        s.done || (reduced && i < 3)
                          ? "border-primary bg-primary text-primary-foreground"
                          : "border-line bg-transparent text-muted-foreground"
                      }`}
                    >
                      {s.done || (reduced && i < 3) ? "✓" : i + 1}
                    </span>
                    <span
                      className={`text-sm ${
                        s.done || (reduced && i < 3)
                          ? "font-medium text-foreground"
                          : "text-muted-foreground"
                      }`}
                    >
                      {s.label}
                    </span>
                    {s.done && i === 2 && !reduced && (
                      <motion.span
                        animate={{ opacity: [0.4, 1, 0.4] }}
                        transition={{ repeat: Infinity, duration: 1.6 }}
                        className="text-xs font-medium text-accent-text"
                      >
                        сейчас здесь
                      </motion.span>
                    )}
                  </div>
                );
              })}
            </div>

            <p className="mt-8 text-sm text-muted-foreground">
              Гарантия 12 месяцев на работы и 6 месяцев на запчасти. 4,9 по
              312 отзывам на картах.
            </p>
          </div>

          <div className="mx-auto w-full max-w-sm">
            <div className="overflow-hidden rounded-2xl border border-line bg-surface-alt shadow-lg">
              <div className="flex items-center gap-3 border-b border-line bg-accent px-4 py-3">
                <div className="flex h-9 w-9 items-center justify-center rounded-full bg-accent-ink text-sm font-bold text-accent">
                  Г
                </div>
                <div>
                  <p className="text-sm font-semibold text-accent-ink">
                    Гараж 24, мастер Илья
                  </p>
                  <p className="text-xs text-accent-ink opacity-70">
                    на связи с 8:00 до 23:00
                  </p>
                </div>
              </div>

              <div className="flex h-[380px] flex-col justify-end gap-2 p-4">
                {messages.slice(0, reduced ? 4 : count).map((m, i) => (
                  <motion.div
                    key={m.time + i}
                    initial={reduced ? false : { opacity: 0, y: 12 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.35 }}
                    className={`max-w-[85%] rounded-2xl px-3.5 py-2.5 ${
                      m.from === "you"
                        ? "self-end rounded-br-sm bg-primary text-primary-foreground"
                        : "self-start rounded-bl-sm bg-background text-foreground border border-line"
                    }`}
                  >
                    {m.photo && (
                      <div className="mb-2 flex items-center gap-2 rounded-lg border border-line bg-surface-alt px-2.5 py-2">
                        <div className="h-8 w-10 rounded bg-primary/20" />
                        <span className="text-[11px] leading-tight text-muted-foreground">
                          {m.photo}
                        </span>
                      </div>
                    )}
                    <p className="text-sm leading-snug">{m.text}</p>
                    <p
                      className={`mt-1 text-right text-[10px] ${
                        m.from === "you"
                          ? "text-primary-foreground opacity-70"
                          : "text-muted-foreground"
                      }`}
                    >
                      {m.time}
                    </p>
                  </motion.div>
                ))}
                {!reduced && count < 4 && (
                  <motion.div
                    animate={{ opacity: [0.3, 1, 0.3] }}
                    transition={{ repeat: Infinity, duration: 1.2 }}
                    className="self-start rounded-2xl border border-line bg-background px-4 py-3"
                  >
                    <div className="flex gap-1">
                      <span className="h-1.5 w-1.5 rounded-full bg-muted-foreground" />
                      <span className="h-1.5 w-1.5 rounded-full bg-muted-foreground" />
                      <span className="h-1.5 w-1.5 rounded-full bg-muted-foreground" />
                    </div>
                  </motion.div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

